extern "C" unsigned int strlen(const char*);

struct string_buf
{
  int pad0;
  int pad4;
  int char_length;
};

class stringx
{
public:
  string_buf* my_buf;

  stringx();
  stringx(const stringx&);
  ~stringx();
  void make_room(int);
  void append(const char*, int = -1);
  void append(const stringx&);
};

inline stringx operator+(const stringx& lhs, const stringx& rhs)
{
  stringx foo;
  foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs);
  return foo;
}

inline stringx operator+(const stringx& lhs, const char* rhs)
{
  stringx foo;
  int len = strlen(rhs);
  foo.make_room(len + lhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs, len);
  return foo;
}

namespace script_object
{
  class instance
  {
  public:
    int pad0;
    stringx name;
    const stringx& get_name() const { return name; }
  };
}

class vm_executable
{
public:
  int pad[3];
  stringx fullname;
  const stringx& get_fullname() const { return fullname; }
};

class vm_thread
{
public:
  script_object::instance* inst;
  const vm_executable* ex;
  script_object::instance* get_instance() const { return inst; }
  const vm_executable* get_executable() const { return ex; }
};

class vm_stack
{
public:
  int salloc;
  char* buffer;
  char* SP;
  vm_thread* my_thread;
  vm_thread* get_thread() const { return my_thread; }
  bool push(const char*, int);
};

class timer_widget;

class script_widget_holder_t
{
public:
  char pad[60];
  timer_widget* my_timer_widget;
  timer_widget* get_timer_widget() const { return my_timer_widget; }
};

class game
{
public:
  char pad[324];
  script_widget_holder_t* script_widget_holder;
  script_widget_holder_t* get_script_widget_holder() const
  {
    return script_widget_holder;
  }
};

extern game* g_game_ptr;
void error(const stringx&);

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t
    {
      FIRST_ENTRY,
      RECALL_ENTRY
    };

    virtual ~function();
    virtual bool operator()(vm_stack&, entry_t) { return true; }
  };
};

typedef timer_widget* vm_timer_widget_t;

class slf_create_timer_widget_t : public script_library_class::function
{
public:
  virtual bool operator()(vm_stack& stack, entry_t entry)
  {
    vm_timer_widget_t result = g_game_ptr->get_script_widget_holder()->get_timer_widget();
    if (!stack.push((char*)&result, sizeof(result)))
      error(stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname());
    return true;
  }
};
